import{_ as n,o as c,c as t,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Spec: Claude CLI cho review và đặt tên trend","description":"","frontmatter":{},"headers":[],"relativePath":"feature/trend-review-cli/spec.md","filePath":"feature/trend-review-cli/spec.md"}'),h={name:"feature/trend-review-cli/spec.md"};function a(o,e,d,l,r,u){return c(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="spec-claude-cli-cho-review-va-đat-ten-trend" tabindex="-1">Spec: Claude CLI cho review và đặt tên trend <a class="header-anchor" href="#spec-claude-cli-cho-review-va-đat-ten-trend" aria-label="Permalink to &quot;Spec: Claude CLI cho review và đặt tên trend&quot;">​</a></h1><h2 id="van-đe" tabindex="-1">Vấn đề <a class="header-anchor" href="#van-đe" aria-label="Permalink to &quot;Vấn đề&quot;">​</a></h2><ul><li>Tên trend trên web chỉ có khoảng 2 từ. Lý do: code đặt tên bằng Claude ở T7 (<code>trend_naming.py</code>) chỉ nằm ở commit local <code>215d8ab</code> và chưa từng lên develop. BE dùng <code>display_name</code> nếu có, nếu không thì dùng <code>keyword</code>.</li><li>Owner muốn chạy Claude qua CLI trên EC2, dùng gói Claude của mình thay cho API key.</li></ul><h2 id="pham-vi" tabindex="-1">Phạm vi <a class="header-anchor" href="#pham-vi" aria-label="Permalink to &quot;Phạm vi&quot;">​</a></h2><ul><li>Khôi phục phần trend của commit <code>215d8ab</code>: kiểm tra nhãn cảm xúc/chủ đề, đặt tên T7, <code>display_name</code>/<code>name_status</code>, export retrain idempotent.</li><li>Thêm <code>TREND_REVIEW_TRANSPORT=api|cli</code>. Khi chọn <code>cli</code>, gọi <code>claude -p</code> trong container ai-service, đăng nhập bằng <code>CLAUDE_CODE_OAUTH_TOKEN</code>.</li><li>Không làm: tạo content khi user request (vẫn theo <code>LLM_PROVIDER</code>), retrain PhoBERT hằng tháng, video edit.</li></ul><h2 id="yeu-cau" tabindex="-1">Yêu cầu <a class="header-anchor" href="#yeu-cau" aria-label="Permalink to &quot;Yêu cầu&quot;">​</a></h2><ul><li>R1: <code>cli</code> phải xóa <code>ANTHROPIC_API_KEY</code>/<code>ANTHROPIC_BASE_URL</code> khỏi môi trường của CLI để tiền tính vào gói của owner.</li><li>R2: Mỗi lần gọi là 1 lượt: không tool, không MCP, không lưu session, system prompt ngắn.</li><li>R3: CLI lỗi, timeout hoặc trả JSON sai thì pipeline giữ nhãn PhoBERT và keyword, không dừng.</li><li>R4: Không có binary <code>claude</code> thì bỏ qua bước review/đặt tên.</li><li>R5: Mặc định vẫn là <code>api</code>.</li></ul><h2 id="rang-buoc" tabindex="-1">Ràng buộc <a class="header-anchor" href="#rang-buoc" aria-label="Permalink to &quot;Ràng buộc&quot;">​</a></h2><ul><li><code>cli</code> chỉ dùng khi một mình owner dùng web. Có người dùng khác thì chuyển về <code>api</code>.</li><li>Token là secret, chỉ để trong <code>.env</code> trên EC2, không commit.</li></ul><h2 id="bo-sung-17-11-2026" tabindex="-1">Bổ sung 17/11/2026 <a class="header-anchor" href="#bo-sung-17-11-2026" aria-label="Permalink to &quot;Bổ sung 17/11/2026&quot;">​</a></h2><ul><li>R6: Trang Explore trends (<code>/ai/trends/explore</code>) trả thêm <code>displayName</code>. <code>keyword</code> vẫn là khóa để tra lịch sử. Ô tìm kiếm khớp cả hai.</li><li>R7: Trend <code>mixed</code> (T4 gom nhiều chuyện vào một keyword): Claude chia thành các chuyện riêng. Mỗi chuyện có ít nhất 2 bài, các chuyện không trùng bài, mỗi chuyện có ít nhất 2 trích dẫn nguyên văn từ 2 bài khác nhau. Mỗi chuyện thành một trend có chủ đề, cảm xúc và bài lấy từ chính bài của nó. Bài lẻ bị bỏ. Không tách được thì giữ trend gốc.</li><li>R8: Neo4j driver kiểm tra kết nối trước khi dùng lại (<code>liveness_check_timeout</code>). Aura tự cắt kết nối rảnh sau các bước Claude/PhoBERT chạy lâu, gây <code>SessionExpired</code>.</li><li>R9: Explore trends ẩn các trend <code>name_status=mixed</code> (bài trùng một từ nhưng không liên quan). Dữ liệu lịch sử trong Neo4j không có trạng thái này nên vẫn hiển thị.</li><li>R10: Biểu đồ lịch sử có thêm đường &quot;tương tác trung bình mỗi bài&quot; = expm1(engagement_score), tính trên like + share của các bài chứa từ khóa chính. Các node cũ cũng tính được.</li><li>R11: Mục bài nguồn hiển thị dạng thẻ (tác giả, nội dung, like/share/comment), lấy <code>post_items</code> từ snapshot hiện tại. Ngày cũ không có trong snapshot thì hiển thị danh sách link như trước.</li><li>R12: Tên trend 5-10 từ, tối đa 60 ký tự, kiểu tiêu đề báo: chuyện chính + điểm khiến người xem quan tâm. Chỉ thêm từ cảm xúc khi bài thể hiện rõ. Tên dài hơn 80 ký tự bị loại.</li><li>R13: Explore trends đánh số rank liên tục trên danh sách đang hiển thị. Lịch sử trend mặc định 7 ngày. Trend chỉ có 1 ngày dữ liệu hiện ghi chú &quot;trend mới&quot; cùng dải tóm tắt cảm xúc và tương tác.</li></ul>',11)])])}const m=n(h,[["render",a]]);export{g as __pageData,m as default};
